WITH filtered AS (SELECT *, LOWER(location) location_lower, COALESCE(dept_name, 'DIRECT') dept_name_clean FROM departments WHERE dept_name = 'HR') SELECT CASE WHEN budget >= 4383000 THEN 'LARGE' ELSE 'SMALL' END AS budget_tier, dept_name, SIZE(COLLECT_SET(dept_name)) AS num_dept_names, SORT_ARRAY(COLLECT_SET(location)) AS location_list, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list, COUNT(DISTINCT location) AS distinct_locations, GROUPING_ID() AS grouping_level FROM filtered GROUP BY GROUPING SETS ((CASE WHEN budget >= 4383000 THEN 'LARGE' ELSE 'SMALL' END, dept_name), (CASE WHEN budget >= 4383000 THEN 'LARGE' ELSE 'SMALL' END), ()) ORDER BY dept_name DESC NULLS FIRST
